testsCode:
import { test } from 'node:test';
import assert from 'node:assert/strict';
import { innerJoin, leftJoin } from './solution.mjs';

const pacientes = [
  { id: 1, nome: 'Ana' },
  { id: 2, nome: 'Beto' },
  { id: 3, nome: 'Caio' },
];
const consultas = [
  { pacienteId: 2, dia: '2026-08-27' },
  { pacienteId: 1, dia: '2026-08-28' },
  { pacienteId: 1, dia: '2026-08-29' },
];

test('innerJoin devolve uma linha por par encontrado (1:N = várias linhas)', () => {
  const juntado = innerJoin(pacientes, 'id', consultas, 'pacienteId');
  assert.equal(juntado.length, 3); // Ana tem 2 consultas, Beto 1
  assert.deepEqual(juntado[0], { id: 1, nome: 'Ana', pacienteId: 1, dia: '2026-08-28' });
  assert.deepEqual(juntado[1], { id: 1, nome: 'Ana', pacienteId: 1, dia: '2026-08-29' });
  assert.equal(juntado[2].nome, 'Beto');
});

test('innerJoin deixa de fora quem não tem par', () => {
  const juntado = innerJoin(pacientes, 'id', consultas, 'pacienteId');
  assert.equal(juntado.some((linha) => linha.nome === 'Caio'), false);
});

test('leftJoin mantém todo mundo de a — quem não tem par entra sozinho', () => {
  const juntado = leftJoin(pacientes, 'id', consultas, 'pacienteId');
  assert.equal(juntado.length, 4);
  const caio = juntado.find((linha) => linha.nome === 'Caio');
  assert.deepEqual(caio, { id: 3, nome: 'Caio' });
});

test('lista b vazia: inner devolve vazio e left devolve a sozinha', () => {
  assert.deepEqual(innerJoin(pacientes, 'id', [], 'pacienteId'), []);
  const sozinhas = leftJoin(pacientes, 'id', [], 'pacienteId');
  assert.deepEqual(sozinhas, pacientes);
});

solutionCode:
// Inner join simulado: para cada linha de a, procura os pares em b
// (linhaB[chaveB] === linhaA[chaveA]) e devolve os dois fundidos.
export function innerJoin(a, chaveA, b, chaveB) {
  const resultado = [];
  for (const linhaA of a) {
    for (const linhaB of b) {
      if (linhaB[chaveB] === linhaA[chaveA]) {
        resultado.push({ ...linhaA, ...linhaB });
      }
    }
  }
  return resultado;
}

// Left join simulado: igual ao inner, mas quem não achou par entra
// sozinho, só com os campos de a (o "null" do SQL vira ausência).
export function leftJoin(a, chaveA, b, chaveB) {
  const resultado = [];
  for (const linhaA of a) {
    const pares = b.filter((linhaB) => linhaB[chaveB] === linhaA[chaveA]);
    if (pares.length === 0) {
      resultado.push({ ...linhaA });
    } else {
      for (const linhaB of pares) {
        resultado.push({ ...linhaA, ...linhaB });
      }
    }
  }
  return resultado;
}
